+import { test, beforeEach } from "node:test";
+import assert from "node:assert/strict";
+import { app } from "../src/api/routes.ts";
+import { resetUsers } from "../src/auth/users.ts";
+import { resetSessions } from "../src/auth/session.ts";
+
+const signup = (body: unknown) => app({ method: "POST", path: "/api/signup", body, headers: {} });
+
+beforeEach(() => {
+  resetUsers();
+  resetSessions();
+});
+
+test("signup creates a public user and a working session", async () => {
+  const res = await signup({ email: "ADA@example.com", name: "Ada", password: "correct horse" });
+  assert.equal(res.status, 201);
+  const { token, user } = res.body as { token: string; user: { id: string; email: string; name: string } };
+  assert.ok(token);
+  assert.deepEqual(user, { id: user.id, email: "ada@example.com", name: "Ada" });
+  const me = await app({ method: "GET", path: "/api/me", headers: { authorization: `Bearer ${token}` } });
+  assert.equal(me.status, 200);
+  assert.deepEqual(me.body, user);
+});
+
+test("signup requires all fields", async () => {
+  const res = await signup({ email: "ada@example.com", password: "correct horse" });
+  assert.equal(res.status, 400);
+  assert.deepEqual(res.body, { error: "email, name and password are required" });
+});
+
+test("signup reports user validation errors", async () => {
+  const invalidEmail = await signup({ email: "invalid", name: "Ada", password: "correct horse" });
+  assert.equal(invalidEmail.status, 400);
+  assert.deepEqual(invalidEmail.body, { error: "invalid email" });
+
+  const shortPassword = await signup({ email: "ada@example.com", name: "Ada", password: "short" });
+  assert.equal(shortPassword.status, 400);
+  assert.deepEqual(shortPassword.body, { error: "password must be at least 8 characters" });
+});
+
+test("signup rejects a duplicate email", async () => {
+  const body = { email: "ada@example.com", name: "Ada", password: "correct horse" };
+  assert.equal((await signup(body)).status, 201);
+  const duplicate = await signup({ ...body, email: "ADA@example.com" });
+  assert.equal(duplicate.status, 400);
+  assert.deepEqual(duplicate.body, { error: "email already registered" });
+});
